1	import type { TrustManifest } from './schema.ts';
2	import type {
3		CorpusConformance,
4		CorpusTransactionState,
5	} from '../../core/src/corpus/conformance.ts';
6	import type { ScriptSurface } from '../../core/src/enterprise/script-surface.ts';
7	import type { RuntimeScriptObservation } from '../../core/src/enterprise/runtime-script-observation.ts';
8	import type { CapabilityCoverage } from '../../core/src/receipts/capability-coverage.ts';
9	
10	interface RenderInputs {
11		manifest: TrustManifest;
12		freeze: Record<string, unknown>;
13		licenses: Record<string, unknown>;
14		vulnerabilities: Record<string, unknown>;
15		matrix: Record<string, unknown>;
16		controls: Record<string, unknown>;
17		conformance: CorpusConformance;
18		scriptSurface: ScriptSurface;
19		runtimeScriptObservation: RuntimeScriptObservation;
20		transaction: CorpusTransactionState;
21		capabilityCoverage: CapabilityCoverage;
22	}
23	
24	/**
25	 * Renders the capability-coverage map: every exported migration capability, the
26	 * independent applications that prove it, and the generality classification
27	 * derived from that proof count. The section is the honest boundary — a
28	 * capability is claimed general (in-matrix) only once at least two independent
29	 * applications prove it, and single-application capabilities are named as
30	 * experimental rather than silently claimed general.
31	 */
32	function capabilityCoverageLines(coverage: CapabilityCoverage): string {
33		const row = (classification: 'cross-proven' | 'experimental'): string =>
34			coverage.capabilities
35				.filter((capability) => capability.classification === classification)
36				.map(
37					(capability) =>
38						`- ${capability.lineage}: \`${capability.name}\` — ${capability.proofCount} application(s)${capability.provenApps.length ? ` (${capability.provenApps.join(', ')})` : ' (unproven coverage)'}`,
39				)
40				.join('\n');
41		return `The map is the machine-readable evidence record [capability-coverage.json](capability-coverage.json); classification is derived from the count of distinct independent applications and is never hand-set. A capability is claimed **general** only once at least ${coverage.crossProvenThreshold} independent applications prove it.
42	
43	- React lineage: ${coverage.summary.react.crossProven}/${coverage.summary.react.total} capabilities cross-proven.
44	- Angular lineage: ${coverage.summary.angular.crossProven}/${coverage.summary.angular.total} capabilities cross-proven.
45	- Total: **${coverage.summary.crossProven} cross-proven (in-matrix)**, **${coverage.summary.experimental} experimental (out-of-matrix)** across ${coverage.summary.total} enumerated capabilities.
46	
47	Cross-proven on at least two independent applications, and therefore in the matrix:
48	
49	${row('cross-proven')}
50	
51	Proven on fewer than two independent applications — single-application or unproven coverage — and therefore **experimental / out-of-matrix**:
52	
53	${row('experimental')}`;
54	}
55	
56	/**
57	 * Reads one lineage readiness score straight out of the emitted conformance.
58	 *
59	 * The Markdown must never restate a numerator; it renders whatever the corpus
60	 * derived, so a prose score cannot drift away from the counted evidence.
61	 */
62	/**
63	 * Renders the holdout ledger the corpus derived.
64	 *
65	 * A holdout is an application the frozen adapters were applied to in order to
66	 * falsify them, and this one failed. The report states the failure, its
67	 * recorded reason, and the fingerprint it ran against, and states in the same
68	 * breath that it is counted in no numerator — so a reader cannot mistake the
69	 * unchanged lineage scores for an absence of contrary evidence.
70	 */
71	function holdoutLines(conformance: CorpusConformance): string {
72		const readiness = (conformance.coverage as Record<string, unknown>).productionReadiness as
73			| Record<string, unknown>
74			| undefined;
75		const holdouts = readiness?.holdouts;
76		if (!Array.isArray(holdouts) || holdouts.length === 0)
77			throw new Error('Corpus conformance omits the holdout ledger');
78		return holdouts
79			.map((value) => {
80				const holdout = value as Record<string, unknown>;
81				/**
82				 * A holdout that is not a failure is rendered by its own sentence rather
83				 * than squeezed into the failure one. The failure sentence says "recorded
84				 * missing capability" and "migrated lane red identically across N
85				 * attempts", and neither is true of a green build; writing it anyway
86				 * would be the report describing a state it did not measure.
87				 *
88				 * The other half of the same rule applies to the pass. This holdout's
89				 * Witness is green on one named surface, so the report states the pass
90				 * and its boundary in one breath — the surface proven, the legs and runs
91				 * behind it, and the surfaces nobody drove — and never contracts it to a
92				 * generic "passed". The earlier RED under the composite this application
93				 * was first frozen against is carried in the same sentence, because a
94				 * report that published only the later state would be hiding the one that
95				 * falsified the frozen adapter.
96				 */
97				if (holdout.outcome !== 'failed')
98					return `- Holdout \`${String(holdout.id)}\` (${String(holdout.application)}, ${String(holdout.lineage)} lineage): **attempted; outcome ${String(holdout.outcome)}**. Baseline lane ${String(holdout.baselineLane)}; migrated lane ${String(holdout.migratedLaneUnderFreeze)} at install against frozen adapter composite \`${String(holdout.frozenAdapterFingerprint)}\` with ${String(holdout.adapterBytesChanged)} adapter bytes changed, and ${String(holdout.migratedLane)} across ${String(holdout.attempts)} byte-identical production builds after the authorized ${String((holdout.authorizedReopen as Record<string, unknown>).task)} Angular-subtree reopen re-frozen at \`${String((holdout.authorizedReopen as Record<string, unknown>).refreezeComposite)}\`. Witness (\`${String(holdout.witnessUnit)}\`): **${String(holdout.witness)}** — ${String(holdout.witnessRuns)} runs over ${String(holdout.witnessLegs)} recorded legs, behaviour parity digest \`${String(holdout.witnessParityDigest)}\`; browser proof **${String(holdout.browserProof)}** on the **${String(holdout.witnessSurface)}** surface only. Still unproven: **${String(holdout.reason)}**. This is a **pass on a bounded surface and not a generic pass**, it is **counted in no lineage numerator**, and the earlier RED is published rather than retracted: [${String(holdout.receipt)}](../../../${String(holdout.receipt)}) \`${String(holdout.digest)}\`.`;
99				return `- Holdout \`${String(holdout.id)}\` (${String(holdout.application)}, ${String(holdout.lineage)} lineage): **attempted; outcome ${String(holdout.outcome)}**. Baseline lane ${String(holdout.baselineLane)}, migrated lane ${String(holdout.migratedLane)} identically across ${String(holdout.attempts)} attempts against frozen adapter composite \`${String(holdout.frozenAdapterFingerprint)}\` with ${String(holdout.adapterBytesChanged)} adapter bytes changed. Recorded missing capability for the follow-on tranche: **${String(holdout.reason)}**. It is **counted in no lineage numerator** and published rather than dropped: [${String(holdout.receipt)}](../../../${String(holdout.receipt)}) \`${String(holdout.digest)}\`.`;
100			})
101			.join('\n');
102	}
103	
104	/**
105	 * Renders the declared support boundaries the corpus derived.
106	 *
107	 * A boundary is the report stating, in the same document as its successes, a
108	 * cell this engine does not support — with the falsification evidence that
109	 * established it and the certification language that keeps it from being read
110	 * as a tested-and-passed cell. It is rendered from the corpus data rather than
111	 * written here, so it cannot quietly stop being said.
112	 */
113	/**
114	 * Renders the amendment a boundary carries beside its declaration.
115	 *
116	 * Three things have to survive into the human report or the report stops being
117	 * honest: the rules the boundary is read by, how often the condition was
118	 * actually observed with tested and screened kept apart, and what population an
119	 * application that clears the gate is drawn from. All three are rendered from
120	 * the corpus data, so stripping them from the data is what it takes to stop
121	 * saying them — and the verifier refuses that.
122	 */
123	function boundaryAmendmentLines(boundary: Record<string, unknown>): string {
124		const amendment = boundary.amendment as
125			| {
126					declaredBy: string;
127					readingRules: Array<{
128						id: string;
129						rule: string;
130						kind: string;
131						neverAnAdapterCapabilityFact: string;
132					}>;
133					prevalence: {
134						statement: string;
135						published: string;
136						tested: { count: number; applications: string[]; strength: string };
137						screened: { count: number; applications: string[]; strength: string };
138						distinctCondition: { application: string; condition: string; countedInPrevalence: boolean };
139					};
140					populationStatement: string;
141			  }
142			| undefined;
143		if (amendment === undefined)
144			throw new Error('A declared support boundary is missing its amendment');
145		const rules = amendment.readingRules
146			.map(
147				(rule) =>
148					`  - Reading rule \`${rule.id}\` (${rule.kind}): ${rule.rule} ${rule.neverAnAdapterCapabilityFact}`,
149			)
150			.join('\n');
151		const prevalence = amendment.prevalence;
152		return `${rules}
153	  - Prevalence (**${prevalence.published}**, ${amendment.declaredBy}): ${prevalence.statement} ${prevalence.tested.count} ${prevalence.tested.strength} (${prevalence.tested.applications.join(', ')}); ${prevalence.screened.count} ${prevalence.screened.strength} (${prevalence.screened.applications.join(', ')}); ${prevalence.distinctCondition.application} carries a ${prevalence.distinctCondition.condition} and is **not counted** in the prevalence.
154	  - Population: ${amendment.populationStatement}`;
155	}
156	
157	function supportBoundaryLines(conformance: CorpusConformance): string {
158		const boundaries = (conformance.coverage as Record<string, unknown>).supportBoundaries;
159		if (!Array.isArray(boundaries) || boundaries.length === 0)
160			throw new Error('Corpus conformance omits the declared support boundaries');
161		return boundaries
162			.map((value) => {
163				const boundary = value as Record<string, unknown>;
164				const evidence = boundary.instanceEvidence as {
165					application: string;
166					receipt: string;
167					libraries: number;
168					importSites: number;
169					digest: string;
170					wall: Array<{ library: string; lastPublishedVersion: string; importSites: string[] }>;
171				};
172				const wall = evidence.wall
173					.map(
174						(entry) =>
175							`\`${entry.library}\` (last published ${entry.lastPublishedVersion}; ${entry.importSites.map((site) => `\`${site}\``).join(', ')})`,
176					)
177					.join(', ');
178				return `- Boundary \`${String(boundary.id)}\` at cell \`${String(boundary.cell)}\` (${String(boundary.lineage)} lineage): **${String(boundary.state)}** — ${String(boundary.condition)}. ${String(boundary.mechanism)} Declared by ${String(boundary.declaredBy)}; **${String(boundary.certification)}**. Instance evidence: ${evidence.application}, ${evidence.libraries} libraries at ${evidence.importSites} import sites — ${wall} — recorded RED in [${evidence.receipt}](../../../${evidence.receipt}) \`${evidence.digest}\`.\n${(boundary.nonclaims as string[]).map((claim) => `  - ${claim}`).join('\n')}\n${boundaryAmendmentLines(boundary)}`;
179			})
180			.join('\n');
181	}
182	
183	function lineageScore(conformance: CorpusConformance, lineage: string): string {
184		const readiness = (conformance.coverage as Record<string, unknown>).productionReadiness as
185			| Record<string, unknown>
186			| undefined;
187		const score = readiness?.[lineage] as { ready: number; total: number } | undefined;
188		if (!score) throw new Error(`Corpus conformance omits ${lineage} readiness`);
189		return `${score.ready}/${score.total}`;
190	}
191	
192	export function renderTrustReport(inputs: RenderInputs): string {
193		const freshness = inputs.manifest.observation.vulnerabilityFreshness;
194		const holdouts = holdoutLines(inputs.conformance);
195		const supportBoundaries = supportBoundaryLines(inputs.conformance);
196		const reactLineage = lineageScore(inputs.conformance, 'reactLineage');
197		const angularLineage = lineageScore(inputs.conformance, 'angularLineage');
198		const freeze = inputs.freeze.freeze as { commit: string; composite: string };
199		const freezeCapabilities = inputs.freeze.capabilities as {
200			experimental: { entries: Array<{ lineage: string; capability: string }> };
201			crossProven: { entries: Array<{ lineage: string; capability: string }> };
202		};
203		const summary = inputs.licenses.summary as Record<string, Record<string, number>>;
204		const expressions = summary.spdxExpression ?? {};
205		const texts = summary.licenseText ?? {};
206		const maintainedReactVerified = inputs.manifest.receipts.some(
207			(item) => item.path === 'evidence/runs/react-boilerplate-v4-node24/t022-run.json',
208		);
209		const vite8ReactVerified = inputs.manifest.receipts.some(
210			(item) => item.path === 'evidence/runs/react-boilerplate-v4-vite8/t028-run.json',
211		);
212		const dataFlowVerified = inputs.manifest.receipts.some(
213			(item) => item.path === 'evidence/runs/react-boilerplate-v4-data-flow/t054-run.json',
214		);
215		const phonecatRouteVerified = inputs.manifest.receipts.some(
216			(item) => item.path === 'evidence/runs/angular-phonecat-route-resolve/t032-run.json',
217		);
218		const phonecatComposedVerified = inputs.manifest.receipts.some(
