		toolAndTargetVersions: {
			tool: {
				generator: 'versionless-local-trust-generator',
				adapterFreezeCommit: asString(freeze.commit, 'freeze commit'),
				adapterFreezeComposite: asString(freeze.composite, 'freeze composite'),
