/**
 * Emits the two enterprise surfaces beside the trust package.
 *
 * They are deliberately derived *after* the manifest rather than folded into
 * the deterministic core: the report quotes the manifest's own digests, which a
 * core member cannot do without hashing itself. The binding is stronger than a
 * hash anyway — verification re-derives both files from the same canonical
 * receipts and compares them byte for byte, so a hand-edited cell fails even if
 * every enclosing hash were recomputed to match it.
 */
export async function writeEnterpriseSurfaces(inputs: {
	root: string;
	output: string;
	manifest: TrustManifest;
	conformance: CorpusConformance;
	capabilityCoverage: ReturnType<typeof buildCapabilityCoverage>;
	matrix: Record<string, unknown>;
	controls: Record<string, unknown>;
	licenses: Record<string, unknown>;
	freeze: Record<string, unknown>;
	scriptSurface: Record<string, unknown>;
	runtimeScriptObservation: Record<string, unknown>;
}): Promise<{ json: unknown; markdown: string }> {
	const cypressWitness = (await verifyHoldoutReactCypressRwaWitnessEvidence(inputs.root)).receipt;
	const workspaceScripts = asRecord(
		asRecord(
			JSON.parse(await readFile(path.join(inputs.root, 'package.json'), 'utf8')),
			'workspace package manifest',
		).scripts,
		'workspace scripts',
	) as Record<string, string>;
	const enterprise = buildEnterpriseReport({
		manifest: inputs.manifest,
		conformance: inputs.conformance,
		capabilityCoverage: inputs.capabilityCoverage,
		matrix: inputs.matrix,
		controls: inputs.controls,
		licenses: inputs.licenses,
		freeze: inputs.freeze,
		scriptSurface: inputs.scriptSurface,
		runtimeScriptObservation: inputs.runtimeScriptObservation,
		cypressWitness,
		workspaceScripts,
	});
	const markdown = renderEnterpriseReport(enterprise);
	assertEnterpriseReport(enterprise, markdown);
	await writeJson(path.join(inputs.output, ENTERPRISE_REPORT_JSON), enterprise);
	await writeFile(path.join(inputs.output, ENTERPRISE_REPORT_MARKDOWN), markdown);
	return { json: enterprise, markdown };
}

